sp_FiltrarPedido	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_FiltrarPedido`(\n\n    IN p_idEmpresa       INT,\n\n    IN p_nomeCliente     VARCHAR(120),\n\n    IN p_numeroExterno   VARCHAR(100),\n\n    IN p_canal           VARCHAR(50),\n\n    IN p_statusPedido_id INT,\n\n    IN p_dthInicio       DATE,\n\n    IN p_dthFim          DATE,\n\n    IN p_valorMin        DECIMAL(10,2),\n\n    IN p_valorMax        DECIMAL(10,2)\n\n)\nBEGIN\n\n    SELECT\n\n        p.idPedido,\n\n        p.numeroPedido,\n\n        p.cliente_id,\n\n        p.idEmpresa,\n\n        c.Nome              AS nomeCliente,\n\n        p.numeroExterno,\n\n        p.canal,\n\n        p.statusPedido_id,\n\n        sp.Nome             AS statusNome,\n\n        p.dthPedido,\n\n        p.valorTotal,\n\n        p.Desconto          AS desconto,\n\n        p.valorFrete,\n\n        p.Observacao        AS observacao,\n\n        COUNT(ip.idPedidoItem) AS totalItens\n\n    FROM Pedido p\n\n    INNER JOIN Cliente      c  ON c.idCliente       = p.cliente_id\n\n    INNER JOIN StatusPedido sp ON sp.idStatusPedido  = p.statusPedido_id\n\n    LEFT  JOIN ItemPedido   ip ON ip.pedido_id       = p.idPedido\n\n    WHERE p.idEmpresa = p_idEmpresa\n\n      AND (p_nomeCliente     IS NULL OR c.Nome          LIKE CONCAT('%', p_nomeCliente,  '%'))\n\n      AND (p_numeroExterno   IS NULL OR p.numeroExterno LIKE CONCAT('%', p_numeroExterno,'%'))\n\n      AND (p_canal           IS NULL OR p.canal          = p_canal)\n\n      AND (p_statusPedido_id IS NULL OR p.statusPedido_id = p_statusPedido_id)\n\n      AND (p_dthInicio       IS NULL OR p.dthPedido      >= p_dthInicio)\n\n      AND (p_dthFim          IS NULL OR p.dthPedido      <= p_dthFim)\n\n      AND (p_valorMin        IS NULL OR p.valorTotal     >= p_valorMin)\n\n      AND (p_valorMax        IS NULL OR p.valorTotal     <= p_valorMax)\n\n    GROUP BY\n\n        p.idPedido, p.numeroPedido, p.cliente_id, p.idEmpresa,\n\n        c.Nome, p.numeroExterno, p.canal, p.statusPedido_id, sp.Nome,\n\n        p.dthPedido, p.valorTotal, p.Desconto, p.valorFrete, p.Observacao\n\n    ORDER BY p.dthPedido DESC, p.idPedido DESC;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
